import {esc,card} from './visuals.mjs';
import {renderWearable} from './on-site-display.mjs';
import {roster,workerStatus,STAGES} from './safety-model.mjs';
const body=h=>`<div class="card-body">${h}</div>`;
const detail=(id,title,h)=>`<details class="ws-details" data-support-details="${id}"><summary>${title}</summary>${body(h)}</details>`;
export function renderWorkerSupport(site){
 const w=site.worker,people=roster(site),status=workerStatus(site),requests=[...status.requests].sort((a,b)=>(b.key==='sos')-(a.key==='sos')),ready=requests.length&&requests.every(e=>e.stage===2);
 const peopleBar=people.map(p=>{const s=workerStatus(site,p);return `<button class="support-person ${s.tone}" data-ws="worker-select" data-value="${esc(p.id)}" aria-pressed="${p.id===w.id}"><strong>${esc(p.name)}</strong><span>${esc(s.label)}</span></button>`;}).join('');
 const conditions=`<div class="support-presets">${[['normal','Normal shift'],['heart','High heart rate'],['long','Extended work']].map(([id,label])=>`<button class="btn" data-ws="worker-case" data-value="${id}" aria-pressed="${w.scenario===id}">${label}</button>`).join('')}</div><label class="support-heat"><input type="checkbox" data-ws-input="weather.heat" ${site.weather.heat?'checked':''}> Hot conditions <small>All workers at ${esc(site.name)}</small></label>${detail('fine','Fine-tune',`<label class="ws-field">Continuous work · ${Math.floor(w.duty)} min<select data-ws-input="support-duty" aria-label="Continuous work minutes">${Array.from({length:17},(_,i)=>`<option value="${i*15}" ${Math.floor(w.duty/15)===i?'selected':''}>${i*15} min</option>`).join('')}</select></label>`)}<p class="note">Changing conditions keeps existing requests open.</p>`;
 const response=requests.length?`<span class="worker-state ${status.tone}">${status.sos?'SOS · urgent support':ready?'Support arranged':'Needs support'}</span><ul class="support-reasons">${requests.map(e=>`<li><strong>${esc(e.title)}</strong><small>${e.condition?'Trigger active':'Trigger cleared · review pending'} · ${e.stage===2?'Arranged':'Awaiting arrangement'}</small></li>`).join('')}</ul><button class="btn" data-ws="${ready?'complete-support':'arrange-support'}">${ready?'Confirm completed':'Arrange support'}</button><p class="note">${ready?'Confirm the simulated handover or assistance is complete.':'Assigns the supervisor and arranges current requests for this worker.'}</p>`:`<span class="worker-state normal">${w.support==='completed'?'Simulated post-support state':'On duty'}</span><p>${w.support==='completed'?'Support recorded. Continuous work reset at completion.':'No open requests for this worker.'}</p>`;
 const rows=people.map(p=>{const s=workerStatus(site,p);return `<tr class="worker-row ${s.tone} ${p.id===w.id?'selected':''}"><th>${esc(p.name)}<small>${esc(p.id)}</small></th><td>${esc(s.label)}</td><td>${p.bpm} bpm</td><td>${Math.floor(p.duty)} min</td></tr>`;}).join('');
 const records=site.events.filter(e=>e.type==='support'&&e.recipient===w.id).map(e=>`<li><strong>${esc(e.title)}</strong><small>${esc(e.id)} · ${STAGES[e.stage]} · ${e.acknowledged?'Acknowledged':'Not acknowledged'}</small><small>${esc(e.result||e.owner||'Unassigned')}</small></li>`).join('');
 return `<section class="support-console"><div class="support-team-heading"><strong>${esc(site.name)} · ${people.filter(p=>workerStatus(site,p).requests.length).length} workers need support</strong><span>Simulated data · Not a health diagnosis</span></div><div class="support-people" aria-label="Select worker">${peopleBar}</div><div class="support-columns">${card('Conditions',`Selected worker · ${esc(w.name)}`,body(conditions))}${card('Worker watch','Simulated wearable',body(renderWearable(site,true)))}${card('Support',esc(w.name),body(response))}</div><div class="support-details">${detail('people','All worker details',`<div class="worker-table-scroll"><table class="worker-table"><thead><tr><th>Worker</th><th>Status</th><th>Heart rate</th><th>Continuous work</th></tr></thead><tbody>${rows}</tbody></table></div>`)}${detail('weather','Other weather conditions',`<p class="note">Site-wide advisories; independent of hot conditions.</p>${[['rain','Rain · check slippery surfaces'],['fog','Low visibility · review sight lines'],['wind','Strong wind · check equipment mounting']].map(([key,label])=>`<label class="support-weather"><input type="checkbox" data-ws-input="weather.${key}" ${site.weather[key]?'checked':''}> ${label}</label>`).join('')}`)}${detail('records',`Support records · ${esc(w.name)}`,`<ul class="support-reasons">${records||'<li>No support records yet.</li>'}</ul><p>Completed support / breaks: ${w.breaks.length}</p>`)}${detail('rules','Simulation rules','<p>High heart rate uses a simulated 148 bpm reading, not a medical threshold. Extended work triggers at 180 minutes. Hot conditions with at least 90 minutes of continuous work trigger a reminder. These are demonstration rules, not approved rest intervals.</p><p>Acknowledgement confirms receipt only. Normal conditions do not close requests. Completion records simulated support, resets continuous work and returns the selected worker to normal readings. Records last for this session; export to retain them.</p>')}</div></section>`;
}
